[FormControlEventHandler(formControlStr(CustTable, NewCustomer), FormControlEventType::Clicked)]
public static void NewCustomer_OnClicked(FormControl sender, FormControlEventArgs e)
{
    boolean                     doCancel;
    FormFunctionButtonControl   ctrl;

    ctrl = sender;
    ctrl.toString();
    //FormDataSourceCancelEventArgs       ce  = e as FormDataSourceCancelEventArgs;
    FormControlCancelableSuperEventArgs sce = e as FormControlCancelableSuperEventArgs;

    doCancel = !AVASalesParameters::checkDirectCustomerCreation(NoYes::Yes);

    if(doCancel)
    {
        //ce.cancel(doCancel);
        sce.CancelSuperCall();
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormControlEventHandler(formControlStr(CustTable, KCS_DirProductGroup_editDirPartyIdRank1), FormControlEventType::Lookup)]
public static void KCS_DirProductGroup_editDirPartyIdRank1_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormRun                 formRun = sender.formRun();
    FormDataSource          dirPartyGroupDS  = formRun.dataSource('KCS_DirProductGroup');
    FormDataSource          custTableDS = formRun.dataSource('CustTable');
    KCS_DirProductGroup     dirProductGroup = dirPartyGroupDS.cursor();
    CustTable               custTable  = custTableDS.cursor();

    DirPartyTable           lookupDirPartyTable;

    KCS_DirProductGroupAddressRanking   locKCS_DirProductGroupAddressRanking;

    locKCS_DirProductGroupAddressRanking = KCS_DirProductGroupAddressRanking::findCommon(dirProductGroup.KCS_DirProductGroupID,
                                                                                         custTable,
                                                                                         KCS_DirProductGrpAddressRanking::one);

    lookupDirPartyTable    = DirPartyTable::findRec(locKCS_DirProductGroupAddressRanking.DirPartyId);


    lookupDirPartyTable    = AVAKBVDirPartyContactPersonHelper::lookupDirPartyRecId(sender, lookupDirPartyTable); //super();


    if (formHasMethod(formRun,'parmDirGroupPartyTable'))
    {
        formRun.parmDirGroupPartyTable(lookupDirPartyTable);

    }

    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    ce.CancelSuperCall();
}

