/// <summary>
///AVA_006850_optimizationBalanceDisplay
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventType</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(CustTable, CustTable), FormDataSourceEventType::Activated)]
public static void CustTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    CredManCreditLimitId					groupTableRecId;
    CredManCreditLimitCustGroup				creditLimitCustGroup;
    CredManCreditLimitCustGroupLine			creditLimitCustGroupLine;
    CustTable                               custTableCaller;
    FormFunctionButtonControl               CustBalanceButton, groupBalanceButton, CustBalanceButtonGroup, groupBalanceButtonGroup;
    boolean                                 isMemberOfCRLGroup;
    FormDataSource                          fds = sender;
    FormFunctionButtonControl               creditLimitAdjTableOpen, creditLimitAdvanced, custGuaranteeInsurance;

    custTableCaller = sender.cursor();
    isMemberOfCRLGroup  = custTableCaller.avaIsMemberOfCreditLimitGroup();

    select firstonly creditLimitCustGroupLine
                    where creditLimitCustGroupLine.custAccount == custTableCaller.AccountNum
                        && creditLimitCustGroupLine.Company == custTableCaller.DataAreaId
                join creditLimitCustGroup
                    where creditLimitCustGroup.RecId == creditLimitCustGroupLine.CreditLimitCustGroup;
    groupTableRecId = creditLimitCustGroup.CreditLimitId;

    CustBalanceButton   = sender.formRun().design().controlName(formControlStr(CustTable, mibCustOpenBalanceCurrency)) as FormFunctionButtonControl;
    groupBalanceButton  = sender.formRun().design().controlName(formControlStr(CustTable, AVAFCMBalance1)) as FormFunctionButtonControl;
    CustBalanceButtonGroup   = sender.formRun().design().controlName(formControlStr(CustTable, CustOpenBalanceCurrency)) as FormFunctionButtonControl;
    //groupBalanceButtonGroup  = sender.formRun().design().controlName(formControlStr(CustTable, AVAFCMBalance)) as FormFunctionButtonControl;
    groupBalanceButtonGroup  = sender.formRun().design().controlName(formControlStr(CustTable, AVAGroupBalance)) as FormFunctionButtonControl;

    if (!groupTableRecId)
    {
        CustBalanceButton.visible(true);
        CustBalanceButtonGroup.visible(true);
        groupBalanceButton.visible(false);
        groupBalanceButtonGroup.visible(false);
    }
    else
    {
        CustBalanceButton.visible(true);
        CustBalanceButtonGroup.visible(false);
        groupBalanceButton.visible(false);
        groupBalanceButtonGroup.visible(true);
    }
    fds.object(fieldNum(CustTable, CreditRating)).allowEdit(!isMemberOfCRLGroup);   
    fds.object(fieldNum(CustTable, MandatoryCreditLimit)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManCustUnlimitedCredit)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManExclude)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManGroupId)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, AVACRLCreditBlocked)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManCustCreditMaxAlt)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CreditMax)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManCreditLimitExpiryDate)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManLastReviewDate)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManNextSchedReviewDate)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManEligibleCreditMax)).allowEdit(!isMemberOfCRLGroup);
    fds.object(fieldNum(CustTable, CredManEligibleCreditLimitCurrency)).allowEdit(!isMemberOfCRLGroup);
    creditLimitAdjTableOpen = sender.formRun().design().controlName(formControlStr(CustTable, CredManCreditLimitAdjTableOpen)) as FormFunctionButtonControl;
    creditLimitAdvanced     = sender.formRun().design().controlName(formControlStr(CustTable, CredManCreditLimitAdvanced)) as FormFunctionButtonControl;
    custGuaranteeInsurance  = sender.formRun().design().controlName(formControlStr(CustTable, CredManCustGuaranteeInsurance)) as FormFunctionButtonControl;

    creditLimitAdjTableOpen.enabled(!isMemberOfCRLGroup);
    creditLimitAdvanced.enabled(!isMemberOfCRLGroup);
    custGuaranteeInsurance.enabled(!isMemberOfCRLGroup);
}
